// https://uinames.com/api/?region=United%20States

var FullName = '';
var Address = '';
var Phone = '';
var PhoneNumber ='';
var Email ='';
var EmailAddress='';
var PolicyClaim='';

var WelcomeMsg='';
var Name='';
var MakeModel='';
var Year='';

if(document.getElementById('conversation-input-text'))
{
  GM_xmlhttpRequest ( {
    method: 'GET',
    url: 'https://icebob.stdlib.com/fake/',
    onload: function (responseDetails) {
    //alert(responseDetails.responseText);

    $data=JSON.parse(responseDetails.responseText);

    FullName = $data.result.lastName+" "+$data.result.firstName;
    PhoneNumber = $data.result.phone;
    EmailAddress = $data.result.email;
     }
} );

//alert(getRandomNum9(9));
//alert(randomString3(3));
//alert(Math.floor((Math.random()*5)+1));
callgm();




}

function callgm() {

setTimeout(function(){ callgm(); }, 3000);

// welcom Message //
if ( document.getElementById("message-container").lastElementChild.innerText.indexOf(' you today') !=-1) {
if (WelcomeMsg=='') { 
		if ( document.getElementById('user-instructions').innerHTML.indexOf('fixing the screen') !=-1 ) { 
			WelcomeMsg ='1';
			document.getElementById('conversation-input-text').value = 'Hi, Good Morning. This is '+ FullName + '. My iPhone screen was just cracked.';
			}
		if ( document.getElementById('user-instructions').innerHTML.indexOf('insurance for one of your') !=-1 ) { 
			WelcomeMsg ='1';
			document.getElementById('conversation-input-text').value = 'Hi, Good Morning. This is '+ FullName + '. I need a insurance copy of my car.';
			}
		if ( document.getElementById('user-instructions').innerHTML.indexOf('status of your claim') !=-1 ) { 
			WelcomeMsg ='1';
			document.getElementById('conversation-input-text').value = 'Hi, Good Morning. This is '+ FullName + '. I wants to know about my claim.';
			}
}
}

// ***************************** //
if ( document.getElementById("message-container").lastElementChild.innerText.indexOf('phone ') !=-1) {
if (phone=='') { 
	phone='1';
			document.getElementById('conversation-input-text').value = PhoneNumber;
}
}
// ***************************** //
if ( document.getElementById("message-container").lastElementChild.innerText.indexOf('email address') !=-1) {
if (Email=='') { 
	Email='1';
			document.getElementById('conversation-input-text').value = EmailAddress;
}
}
// ***************************** //
if ( document.getElementById("message-container").lastElementChild.innerText.indexOf('policy') !=-1 || document.getElementById("message-container").lastElementChild.innerText.indexOf('claim') !=-1) {
if (PolicyClaim=='') { 
	PolicyClaim='1';

			document.getElementById('conversation-input-text').value = 'Policy Number : '+randomString3(3)+getRandomNum9(9) ' & ' + 'Claim Number : '+randomString3(3)+getRandomNum9(3);
}
}


// ***************************** //
if ( document.getElementById("message-container").lastElementChild.innerText.indexOf('make') !=-1 && document.getElementById("message-container").lastElementChild.innerText.indexOf('model') !=-1) {
if (MakeModel=='') { 
	MakeModel='1';

